        if (k == 0) return 1L
        var p = power(a, k shr 1)
        p = p * p % MD
        if (k and 1 == 1) p = p * a % MD
        return p
    }

    fun ch(n: Int, k: Int): Long {
        return ff[n].toLong() * gg[k] % MD * gg[n - k] % MD
    }

    fun run() {
        val n = sc.nextInt()
        val k_ = sc.nextLong()
